window.SETTINGS_ICON = "data:image/png;base64,";
/* common.js — shared FIXERR UI helpers (loaders, pagination, modals).
   Loaded by the customer, professional and admin dashboards so the same, consistent
   behaviour is reused everywhere instead of being duplicated per page. Framework-free,
   matches the existing theme via the page's CSS variables (--accent, --border, etc.). */
(function () {
  if (window.FXUI) return; // guard against double-inclusion

  // Inject the spinner keyframes + pagination styles once.
  var style = document.createElement('style');
  style.textContent = [
    '@keyframes fx-spin{to{transform:rotate(360deg)}}',
    '.fx-spin{display:inline-block;border-radius:50%;border-style:solid;border-color:currentColor;border-top-color:transparent;animation:fx-spin .6s linear infinite;vertical-align:-2px}',
    '.fx-pager{display:flex;flex-wrap:wrap;align-items:center;gap:.35rem;justify-content:center;margin-top:1rem;font-size:.82rem}',
    '.fx-pager button{min-width:34px;height:34px;padding:0 .55rem;border:1.5px solid var(--border,#e5e7eb);background:#fff;color:var(--text,#111);border-radius:8px;cursor:pointer;font-weight:600;font-size:.82rem;line-height:1}',
    '.fx-pager button:hover:not(:disabled){border-color:var(--accent,#3D8B37);color:var(--accent,#3D8B37)}',
    '.fx-pager button.act{background:var(--accent,#3D8B37);color:#fff;border-color:var(--accent,#3D8B37)}',
    '.fx-pager button:disabled{opacity:.45;cursor:not-allowed}',
    '.fx-pager .fx-ellipsis{padding:0 .2rem;color:var(--muted,#6b7280)}',
    '.fx-pager .fx-jump{display:flex;align-items:center;gap:.3rem;margin-left:.4rem;color:var(--muted,#6b7280)}',
    '.fx-pager .fx-jump input{width:52px;height:34px;border:1.5px solid var(--border,#e5e7eb);border-radius:8px;padding:0 .4rem;font-size:.82rem;text-align:center}',
    '.fx-modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:10000;display:flex;align-items:center;justify-content:center;padding:1rem;overflow-y:auto}',
    '.fx-modal{background:#fff;border-radius:14px;width:100%;max-width:560px;box-shadow:0 24px 60px rgba(0,0,0,.25);max-height:92vh;display:flex;flex-direction:column;animation:fx-pop .16s ease-out}',
    '@keyframes fx-pop{from{transform:translateY(8px) scale(.98);opacity:.6}to{transform:none;opacity:1}}',
    '.fx-modal-head{display:flex;justify-content:space-between;align-items:center;padding:1.1rem 1.35rem;border-bottom:1px solid var(--border,#e5e7eb)}',
    '.fx-modal-head h3{margin:0;font-size:1.05rem;font-weight:800}',
    '.fx-modal-x{background:none;border:none;font-size:1.4rem;line-height:1;cursor:pointer;color:var(--muted,#6b7280)}',
    '.fx-modal-body{padding:1.35rem;overflow-y:auto}',
    '.fx-kv{display:grid;grid-template-columns:140px 1fr;gap:.5rem .75rem;font-size:.88rem}',
    '.fx-kv dt{color:var(--muted,#6b7280);font-weight:600}',
    '.fx-kv dd{margin:0;font-weight:600;word-break:break-word}',
    '.fx-field{margin-bottom:.85rem}',
    '.fx-field label{display:block;font-size:.78rem;font-weight:700;margin-bottom:.3rem;color:var(--text,#111)}',
    '.fx-field input,.fx-field select{width:100%;box-sizing:border-box;border:1.5px solid var(--border,#e5e7eb);border-radius:8px;padding:.6rem .75rem;font-size:.9rem}',
    '.fx-grid2{display:grid;grid-template-columns:1fr 1fr;gap:.75rem}',
    '@media(max-width:540px){.fx-kv{grid-template-columns:1fr}.fx-kv dt{margin-top:.4rem}.fx-grid2{grid-template-columns:1fr}}',
    '.fx-colwrap{position:relative;display:inline-block}',
    '.fx-colbtn{display:inline-flex;align-items:center;gap:.3rem;border:1.5px solid var(--border,#e5e7eb);background:#fff;color:var(--text,#111);border-radius:50px;padding:.4rem .8rem;font-size:.82rem;font-weight:600;cursor:pointer;white-space:nowrap}',
    '.fx-colbtn:hover{border-color:var(--accent,#3D8B37);color:var(--accent,#3D8B37)}',
    '.fx-colpanel{position:absolute;top:calc(100% + 5px);right:0;z-index:60;background:#fff;border:1px solid var(--border,#e5e7eb);border-radius:10px;box-shadow:0 12px 32px rgba(0,0,0,.16);padding:.35rem;min-width:200px;max-height:340px;overflow-y:auto}',
    '.fx-colpanel label{display:flex;align-items:center;gap:.55rem;padding:.42rem .55rem;font-size:.84rem;border-radius:6px;cursor:pointer;white-space:nowrap}',
    '.fx-colpanel label:hover{background:var(--bg2,#f3f4f6)}',
    '.fx-colpanel input[type=checkbox]{width:16px;height:16px;accent-color:var(--accent,#3D8B37);cursor:pointer;flex-shrink:0}',
    '.fx-colhint{font-size:.7rem;color:var(--muted,#6b7280);padding:.35rem .55rem;border-top:1px solid var(--border,#e5e7eb);margin-top:.25rem}',
    '.fx-pager-info{text-align:center;font-size:.76rem;color:var(--muted,#6b7280);margin-top:.7rem}',
    '.fx-pager-info+.fx-pager{margin-top:.4rem}',
    '.fx-overlay{position:fixed;inset:0;z-index:100000;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.9rem;background:rgba(255,255,255,.92);backdrop-filter:blur(2px)}',
    '.fx-overlay .fx-ov-msg{font-size:.9rem;font-weight:600;color:var(--accent,#3D8B37)}'
  ].join('');
  document.head.appendChild(style);

  function esc(v) {
    if (v === null || v === undefined) return '';
    return String(v).replace(/[&<>"']/g, function (m) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m];
    });
  }

  var FXUI = {
    esc: esc,

    // Fetches an invoice with the auth token attached (instead of a plain <a href> which would
    // leak the booking ref in a URL any unauthenticated request could hit) and opens the
    // returned HTML in a new tab via a blob URL.
    openInvoice: function (bookingRef, evt) {
      if (evt && evt.preventDefault) evt.preventDefault();
      var win = window.open('', '_blank');
      var token = localStorage.getItem('fx_tok');
      fetch('/api/invoices/' + encodeURIComponent(bookingRef) + '/download', {
        headers: token ? { 'Authorization': 'Bearer ' + token } : {}
      }).then(function (res) {
        if (!res.ok) return res.json().catch(function () { return {}; }).then(function (body) {
          throw new Error(body.error || 'Could not load invoice (' + res.status + ')');
        });
        return res.blob();
      }).then(function (blob) {
        var url = URL.createObjectURL(blob);
        if (win) { win.location = url; }
        else { window.open(url, '_blank'); }
        setTimeout(function () { URL.revokeObjectURL(url); }, 60000);
      }).catch(function (err) {
        if (win) win.close();
        if (typeof toast === 'function') toast(err.message || 'Could not load invoice', 'err');
        else alert(err.message || 'Could not load invoice');
      });
    },

    spinner: function (size, color) {
      size = size || 16;
      return '<span class="fx-spin" style="width:' + size + 'px;height:' + size + 'px;border-width:2px;' +
        (color ? 'color:' + color + ';' : '') + '"></span>';
    },

    // Run an async action tied to a button: disables it, shows a spinner + label, prevents
    // duplicate clicks, and always restores the original content afterwards.
    busy: async function (btn, fn, label) {
      if (!btn) return fn();
      if (btn.dataset.fxBusy === '1') return; // duplicate-request guard
      btn.dataset.fxBusy = '1';
      var original = btn.innerHTML;
      var w = btn.offsetWidth;
      btn.disabled = true;
      if (w) btn.style.minWidth = w + 'px';
      btn.innerHTML = this.spinner(14, '#fff') + (label ? ' ' + esc(label) : '');
      try {
        return await fn();
      } finally {
        btn.disabled = false;
        btn.innerHTML = original;
        btn.style.minWidth = '';
        btn.dataset.fxBusy = '0';
      }
    },

    // Slice an array for the given 1-based page. Returns {slice,page,totalPages,total,per}.
    paginate: function (arr, page, per) {
      per = per || 10;
      arr = arr || [];
      var totalPages = Math.max(1, Math.ceil(arr.length / per));
      var p = Math.min(Math.max(1, parseInt(page, 10) || 1), totalPages);
      return { slice: arr.slice((p - 1) * per, p * per), page: p, totalPages: totalPages, total: arr.length, per: per };
    },

    // Render responsive pagination controls into containerEl. onGo(pageNum) is invoked on change.
    // opts.jump=true adds a "Page: [ ] Go" input box (validated).
    renderPagination: function (containerEl, state, onGo, opts) {
      if (!containerEl) return;
      opts = opts || {};
      var page = state.page, total = state.totalPages;
      var per = state.per || 10, records = state.total || 0;
      if (records === 0) { containerEl.innerHTML = ''; return; }

      // Summary line — total records, current page, total pages (shown whenever there is data).
      var start = (page - 1) * per + 1;
      var end = Math.min(page * per, records);
      var summary = '<div class="fx-pager-info">Showing <b>' + start + '–' + end + '</b> of <b>' + records +
        '</b> record' + (records === 1 ? '' : 's') + ' · Page <b>' + page + '</b> of <b>' + total + '</b></div>';
      if (total <= 1) { containerEl.innerHTML = summary; return; }

      // Windowed page numbers: first, last, and current ±1, with ellipses.
      var nums = [];
      for (var i = 1; i <= total; i++) {
        if (i === 1 || i === total || (i >= page - 1 && i <= page + 1)) nums.push(i);
        else if (nums[nums.length - 1] !== '…') nums.push('…');
      }

      var html = '<div class="fx-pager">';
      html += '<button ' + (page <= 1 ? 'disabled' : '') + ' data-go="' + (page - 1) + '">‹ Prev</button>';
      nums.forEach(function (n) {
        if (n === '…') html += '<span class="fx-ellipsis">…</span>';
        else html += '<button class="' + (n === page ? 'act' : '') + '" data-go="' + n + '">' + n + '</button>';
      });
      html += '<button ' + (page >= total ? 'disabled' : '') + ' data-go="' + (page + 1) + '">Next ›</button>';
      if (opts.jump) {
        html += '<span class="fx-jump">Page: <input type="number" id="fx-pager-jump" name="fx-pager-jump" min="1" max="' + total + '" value="' + page +
          '" aria-label="Go to page"><button type="button" data-jump="1">Go</button></span>';
      }
      html += '</div>';
      containerEl.innerHTML = summary + html;

      containerEl.querySelectorAll('button[data-go]').forEach(function (b) {
        b.addEventListener('click', function () { onGo(parseInt(b.getAttribute('data-go'), 10)); });
      });
      var jumpBtn = containerEl.querySelector('button[data-jump]');
      if (jumpBtn) {
        var input = containerEl.querySelector('.fx-jump input');
        var doJump = function () {
          var v = parseInt(input.value, 10);
          if (!v || v < 1 || v > total) { input.value = page; input.style.borderColor = '#DC2626'; setTimeout(function () { input.style.borderColor = ''; }, 900); return; }
          onGo(v);
        };
        jumpBtn.addEventListener('click', doJump);
        input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); doJump(); } });
      }
    },

    // Open a responsive modal. Returns the .fx-modal-body element for further wiring.
    openModal: function (title, bodyHtml, maxWidth) {
      this.closeModal();
      var overlay = document.createElement('div');
      overlay.className = 'fx-modal-overlay';
      overlay.id = 'fx-modal-overlay';
      overlay.innerHTML =
        '<div class="fx-modal"' + (maxWidth ? ' style="max-width:' + maxWidth + 'px"' : '') + '>' +
        '<div class="fx-modal-head"><h3>' + esc(title) + '</h3><button class="fx-modal-x" aria-label="Close">&times;</button></div>' +
        '<div class="fx-modal-body">' + bodyHtml + '</div></div>';
      document.body.appendChild(overlay);
      overlay.addEventListener('click', function (e) { if (e.target === overlay) FXUI.closeModal(); });
      overlay.querySelector('.fx-modal-x').addEventListener('click', function () { FXUI.closeModal(); });
      document.addEventListener('keydown', FXUI._escClose);
      return overlay.querySelector('.fx-modal-body');
    },

    closeModal: function () {
      var el = document.getElementById('fx-modal-overlay');
      if (el) el.remove();
      document.removeEventListener('keydown', FXUI._escClose);
    },

    // Alias — some callers use FXUI.modal(); keep it working as openModal().
    modal: function (title, bodyHtml, maxWidth) {
      return this.openModal(title, bodyHtml, maxWidth);
    },

    // Centered Delete Confirmation Modal with Cancel & Delete buttons
    confirmDelete: function (title, messageHtml, onConfirm) {
      var content =
        '<div style="text-align:center;padding:0.4rem 0.2rem;">' +
          '<div style="font-size:2.2rem;margin-bottom:0.4rem;">🗑️</div>' +
          '<h3 style="font-size:1.1rem;font-weight:700;margin-bottom:0.5rem;color:var(--text,#1f2937);">' + (title || 'Confirm Deletion') + '</h3>' +
          '<div style="font-size:0.86rem;color:var(--muted,#6b7280);margin-bottom:1.4rem;line-height:1.5;">' + (messageHtml || 'Are you sure you want to delete this record? This action cannot be undone.') + '</div>' +
          '<div style="display:flex;gap:0.75rem;justify-content:center;">' +
            '<button type="button" id="fx-del-cancel" class="btn-ghost btn-sm" style="padding:0.45rem 1.25rem;border-radius:8px;font-weight:600;border:1px solid #D1D5DB;background:#fff;cursor:pointer;font-size:0.85rem;">Cancel</button>' +
            '<button type="button" id="fx-del-confirm" class="btn-primary btn-sm" style="padding:0.45rem 1.25rem;border-radius:8px;font-weight:600;background:#DC2626;color:#fff;border:none;cursor:pointer;box-shadow:0 2px 4px rgba(220,38,38,0.25);font-size:0.85rem;">Delete</button>' +
          '</div>' +
        '</div>';

      var body = this.openModal(title || 'Delete Confirmation', content, 420);
      var cancelBtn = document.getElementById('fx-del-cancel');
      var confirmBtn = document.getElementById('fx-del-confirm');
      if (cancelBtn) cancelBtn.addEventListener('click', function () { FXUI.closeModal(); });
      if (confirmBtn) confirmBtn.addEventListener('click', function () {
        FXUI.closeModal();
        if (typeof onConfirm === 'function') onConfirm();
      });
    },

    _escClose: function (e) { if (e.key === 'Escape') FXUI.closeModal(); },

    // Spinner row for a table body while its data loads.
    tableLoading: function (tbody, colspan, msg) {
      var tb = typeof tbody === 'string' ? document.getElementById(tbody) : tbody;
      if (tb) tb.innerHTML = '<tr><td colspan="' + (colspan || 12) + '" style="padding:2rem;text-align:center;color:var(--muted,#6b7280);">' +
        this.spinner(20, 'var(--accent,#3D8B37)') + ' ' + esc(msg || 'Loading…') + '</td></tr>';
    },

    // Full-page loading overlay — used during the login → dashboard transition so the user
    // sees a spinner until the next page takes over.
    pageLoading: function (show, msg) {
      var el = document.getElementById('fx-page-overlay');
      if (show) {
        if (!el) {
          el = document.createElement('div');
          el.id = 'fx-page-overlay';
          el.className = 'fx-overlay';
          el.innerHTML = this.spinner(42, 'var(--accent,#3D8B37)') + '<div class="fx-ov-msg">' + esc(msg || 'Loading…') + '</div>';
          document.body.appendChild(el);
        }
      } else if (el) { el.remove(); }
    },

    // Read-only "form input" view: rows = [[label,value], ...] rendered as disabled fields.
    readonlyForm: function (rows) {
      return '<div class="fx-grid2">' + rows.map(function (kv, i) {
        var slug = String(kv[0]).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || ('field-' + i);
        var fid = 'fx-ro-' + slug + '-' + i;
        return '<div class="fx-field"><label for="' + fid + '">' + esc(kv[0]) + '</label>' +
          '<input type="text" id="' + fid + '" name="' + fid + '" value="' + esc(kv[1] != null && kv[1] !== '' ? kv[1] : '—') + '" readonly ' +
          'style="background:var(--bg2,#f3f4f6);cursor:default;"></div>';
      }).join('') + '</div>';
    },

    // Column chooser: a "Columns ▾" dropdown of checkboxes that show/hide table columns
    // (by nth-child), persisted in localStorage. Columns named in `mandatory` (default
    // "Action"/"Actions") are always shown and cannot be toggled off.
    columnChooser: function (table, opts) {
      opts = opts || {};
      if (typeof table === 'string') table = document.getElementById(table);
      var mount = typeof opts.mount === 'string' ? document.getElementById(opts.mount) : opts.mount;
      if (!table || !mount) return;
      if (!table.id) table.id = 'fxtbl-' + Math.random().toString(36).slice(2, 8);
      var headers = [].slice.call(table.querySelectorAll('thead th')).map(function (th, i) {
        return { idx: i + 1, label: (th.textContent || '').trim() || ('Column ' + (i + 1)) };
      });
      var mand = (opts.mandatory || ['action', 'actions']).map(function (s) { return s.toLowerCase(); });
      var key = 'fxcols_' + (opts.key || table.id);
      var saved = localStorage.getItem(key);
      var hidden = {};
      if (saved) {
        try { hidden = JSON.parse(saved); } catch (e) {}
      } else if (opts.hiddenByDefault && opts.hiddenByDefault.length) {
        // First-ever init (no saved preference): hide these columns by default.
        var defHide = opts.hiddenByDefault.map(function (s) { return s.toLowerCase(); });
        headers.forEach(function (h) { if (defHide.indexOf(h.label.toLowerCase()) !== -1) hidden[h.idx] = 1; });
      }
      var styleEl = document.getElementById(table.id + '-cstyle');
      if (!styleEl) { styleEl = document.createElement('style'); styleEl.id = table.id + '-cstyle'; document.head.appendChild(styleEl); }
      var isMand = function (h) { return mand.indexOf(h.label.toLowerCase()) !== -1; };
      function apply() {
        var rules = headers.filter(function (h) { return hidden[h.idx] && !isMand(h); }).map(function (h) {
          return '#' + table.id + ' th:nth-child(' + h.idx + '),#' + table.id + ' td:nth-child(' + h.idx + '){display:none !important}';
        });
        styleEl.textContent = rules.join('');
        try { localStorage.setItem(key, JSON.stringify(hidden)); } catch (e) {}
      }
      apply();
      mount.innerHTML = '';
      var wrap = document.createElement('div'); wrap.className = 'fx-colwrap';
      var btn = document.createElement('button'); btn.type = 'button'; btn.className = 'fx-colbtn'; btn.innerHTML = '🧩 Columns ▾';
      var panel = document.createElement('div'); panel.className = 'fx-colpanel'; panel.style.display = 'none';
      panel.innerHTML = headers.map(function (h) {
        var m = isMand(h);
        var cbId = 'fx-col-' + table.id + '-' + h.idx;
        return '<label for="' + cbId + '"><input type="checkbox" id="' + cbId + '" name="' + cbId + '" data-idx="' + h.idx + '" ' + (!hidden[h.idx] || m ? 'checked' : '') + ' ' + (m ? 'disabled' : '') + '>' +
          esc(h.label) + (m ? ' <span style="color:var(--muted,#6b7280);font-size:.7rem;">(required)</span>' : '') + '</label>';
      }).join('') + '<div class="fx-colhint">Select columns to display</div>';
      wrap.appendChild(btn); wrap.appendChild(panel); mount.appendChild(wrap);
      btn.addEventListener('click', function (e) { e.stopPropagation(); panel.style.display = panel.style.display === 'none' ? 'block' : 'none'; });
      panel.addEventListener('click', function (e) { e.stopPropagation(); });
      [].slice.call(panel.querySelectorAll('input[data-idx]')).forEach(function (cb) {
        cb.addEventListener('change', function () {
          var idx = +cb.getAttribute('data-idx');
          if (cb.checked) delete hidden[idx]; else hidden[idx] = 1;
          apply();
        });
      });
      document.addEventListener('click', function () { panel.style.display = 'none'; });
    }
  };

  window.FXUI = FXUI;
})();
